Translate("deDE", "un-goro-crater", {
	title = "Un'Goro-Krater",
	aliases = { "Un'Goro", "der Krater" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Un'Goro-Krater ist ein riesiges grünes Becken, tief in den Süden von {link:kalimdor}Kalimdor{/link} eingesunken, von Klippen umschlossen zwischen den Sanden von {link:tanaris}Tanaris{/link} und den verseuchten Ödlanden von {link:silithus}Silithus{/link}. Unterhalb seines Randes scheint die Welt einem anderen Zeitalter anzugehören. Dampf steigt aus seinen Quellen, ein Vulkan raucht in seinem Herzen, und der Dschungel wird von Tieren beherrscht, die der Rest der Welt längst vergessen hat: donnernde Teufelssaurier, Stegodonten, geflügelte Pterrordax und Rudel von Ravasauriern. Seltsame Kristalle glitzern im Gras, und hohe {link:crystal-pylons}Pylonen aus Kristall{/link} stehen am Rand der Wildnis.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wie der Krater entstand, noch wann. Die Geschichten des frühesten Zeitalters besagen, dass die Diener der {red:titans}Titanen{/red} gewisse Länder der jungen Welt als Gärten wilden Lebens formten und dass Un'Goro eines davon war. Die {link:crystal-pylons}Pylonen aus Kristall{/link}, die um seinen Rand stehen, sind älter als jedes Volk, das heute in {link:kalimdor}Kalimdor{/link} lebt, und niemand, der heute im Krater wohnt, kann sagen, wer sie errichtete oder warum. Die {link:tauren}Tauren{/link}, die hierher zum Jagen kommen, spüren die Gegenwart der Erdmutter im Becken stark. Für sie sind seine Geschöpfe die edleren Verwandten der Tiere ihrer eigenen Ebenen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der Krater hat in letzter Zeit eine Schar von Neugierigen und Gestrandeten angezogen. Eine Truppe von Forschern unter {link:williden-marshal}Williden Marshal{/link} kam, um das Land zu erforschen, und wurde von ihm beinahe vernichtet. Ihre Überlebenden halten eine felsige Zuflucht auf den nördlichen Höhen, wo sich Goblins aus {link:gadgetzan}Gadgetzan{/link}, umherziehende Gelehrte und verirrte Reisende um sie geschart haben. Der {link:cenarion-circle}Zirkel des Cenarius{/link} hat nach der Erde des Kraters geschickt, die starke Magie bergen soll, und Druiden in {link:darnassus}Darnassus{/link} und {link:thunder-bluff}Thunder Bluff{/link} erforschen sie. Im Süden haben sich die Insekten des Stocks der Gorishi in die Erde gegraben. Ihre Anwesenheit beunruhigt die Gelehrten, denn nichts wie sie gehört zur natürlichen Ordnung des Kraters. In diesen Tagen nennen die Karten auch die {red:shaper-s-terrace}Shaper's Terrace{/red} im Krater, einen Ort, dessen Geschichte auf seiner eigenen Seite erzählt wird.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die großen Saurier.{/b} Teufelssaurier jagen im ganzen Becken. Stegodonten grasen im Südwesten, Ravasaurier laufen im Südosten in Rudeln, und Diemetradons sonnen sich an seinen Pfaden.
• {b}Die Affen von {link:fungal-rock}Fungal Rock{/link}.{/b} Große Gorillas halten die Höhlen im Nordosten und vertreiben jeden, der sich nähert.
• {b}Die Gorishi.{/b} Ein Stock von Insekten hat sich die wuchernde Narbe im Süden ausgehöhlt.
• {b}Elementare.{/b} Wesen aus lebendiger Flamme wandeln über die Hänge des Vulkans, und Geschöpfe aus Teer erheben sich aus den nördlichen Gruben.
• {b}Blutblütler und Schlammwesen.{/b} Fleischfressende Pflanzen kriechen durch die östlichen Dickichte, und Schleime sammeln sich in den {link:the-marshlands}Marschen{/link}.
• {b}Die Neuankömmlinge.{/b} Forscher, Tüftler aus {link:gadgetzan}Gadgetzan{/link} und verirrte Wanderer drängen sich in {link:marshal-s-refuge}Marshals Zuflucht{/link}, und ein Jäger der {link:tauren}Tauren{/link} unterhält sein eigenes Lager dort, wo die Straße aus {link:tanaris}Tanaris{/link} in den Krater führt.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Schöpfer.{/b} Die Pylonen und Kristalle des Kraters sind aus einer Zeit vor jedem sterblichen Königreich übrig. Keine sterbliche Geschichte verzeichnet ihre Errichtung.
• {b}Die Expedition der Marshals.{/b} Die Truppe von {link:williden-marshal}Williden Marshal{/link} errichtete Lager im Südwesten und Nordosten des Kraters. Die Tiere überrannten beide, und die Überlebenden flohen nach Norden auf höheren Grund.
• {b}Die Gegenwart.{/b} Gelehrte, Druiden, Jäger und mindestens ein Wanderer, der sich nicht erinnern kann, warum er kam, suchen nun den Krater auf.]=],
		},
		{
			title = "Überlieferungen des Kraters",
			text = [=[• In {link:marshal-s-refuge}Marshals Zuflucht{/link} sagt man, dass die Pylonen und die farbigen Kristalle im Gras zusammengehören und dass die richtige Mischung der Farben ihre Macht wecken wird.
• {link:krakle}Krakle{/link} aus {link:gadgetzan}Gadgetzan{/link} glaubt, dass die Quellen von {link:golakka-hot-springs}Golakka{/link} ihre Wärme aus dem Vulkan beziehen, auch wenn seine Berechnungen noch nicht abgeschlossen sind.
• {link:torwa-pathfinder}Torwa Pathfinder{/link} warnt, dass {link:lar-korwi}Lar'korwi{/link}, der große Ravasaurier des Ostens, jedem tagelang folgt, der von seiner Beute stiehlt.]=],
		},
	},
})

Translate("deDE", "marshal-s-refuge", {
	title = "Marshals Zuflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marshals Zuflucht ist ein Lager aus Zelten und Kochfeuern zwischen den Felsen der Nordwand des Kraters. Es wurde auf der Flucht gegründet. Als die Tiere von {link:un-goro-crater}Un'Goro{/link} die Lager der Marshal Expeditions überrannten, kletterten {link:williden-marshal}Williden Marshal{/link} und seine Leute auf diesen hohen Grund, wohin die großen Saurier ihnen nicht leicht folgen konnten. Andere haben sich ihnen seither angeschlossen: ein Flugmeister aus {link:gadgetzan}Gadgetzan{/link}, verirrte Wanderer, streitende Reisende und eine Kristallforscherin, die in der Höhle über dem Lager arbeitet. {link:refuge-pointe}Die Zuflucht{/link} ist der einzige Ort im Krater, an dem ein Reisender schlafen kann, ohne ein Auge offen zu halten.]=],
		},
	},
})

Translate("deDE", "fire-plume-ridge", {
	title = "Der Feuerfedergrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Feuerfedergrat ist der Vulkan im Zentrum von {link:un-goro-crater}Un'Goro{/link}, ein verkohlter Kegel, der Rauch und Hitze über den ganzen Krater ergießt. Seine Hänge gehören Elementaren aus lebendiger Flamme. In seinem Herzen, auf Pfaden aus geschwärztem Fels, haust {link:blazerunner}Blazerunner{/link}, ein Elementar, gehüllt in eine Aura, die noch keine Klinge durchdrungen hat. Er bewacht eine Höhle, die die Goldene Flamme birgt. Die Hitze des Grats ist heftig genug, um Unvorsichtige zu überwältigen, und der Forscher {link:ringo}Ringo{/link} wäre beinahe daran gestorben. Wer den Krater erforscht, glaubt, dass der Vulkan seine Quellen erwärmen könnte.]=],
		},
	},
})

Translate("deDE", "golakka-hot-springs", {
	title = "Die heißen Quellen von Golakka",
	aliases = { "Golakka" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die heißen Quellen von Golakka dampfen im westlichen Teil des Kraters, eine Kette warmer Becken inmitten des Dschungels. {link:krakle}Krakle{/link}, ein Gelehrter aus {link:gadgetzan}Gadgetzan{/link}, hat sein Lager neben ihnen aufgeschlagen, fern von der Sicherheit der Zuflucht. Er will wissen, woher ihre Wärme kommt, und er hat den Vulkan des Feuerfedergrats nicht weit im Osten in Verdacht. Seine Messungen haben ihn dazu gebracht, über andere Quellen im fernen {link:winterspring}Winterspring{/link} nachzudenken, wo es überhaupt keinen Vulkan gibt.]=],
		},
	},
})

Translate("deDE", "lakkari-tar-pits", {
	title = "Teergruben von Lakkari",
	aliases = { "Lakkari" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Teergruben von Lakkari liegen im Norden des Kraters, südlich von {link:marshal-s-refuge}Marshals Zuflucht{/link}. Schwarzer Teer brodelt hier in breiten, klebrigen Becken aus dem Boden. Aus ihm erheben sich Geschöpfe aus Teer, die aus eigenem Willen zu leben und sich zu bewegen scheinen. Die größten von ihnen, die Teerfürsten, lauern nahe den nördlichen Becken. Geringere Teerbestien und Teerkriecher wandern weiter nach Süden, zu den Ebenen unterhalb des Vulkans. Keine Aufzeichnung sagt, wer den Gruben ihren Namen gab.]=],
		},
	},
})

Translate("deDE", "the-slithering-scar", {
	title = "Die wuchernde Narbe",
	aliases = { "Wuchernde Narbe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die wuchernde Narbe ist ein großer Riss im südlichen Boden des Kraters, wo die Insekten der Gorishi ihren Stock gebaut haben. Wespen erfüllen die Luft darüber, und Arbeiter, Häscher und Tunnelgräber krabbeln durch seine Gänge. In tiefen Kammern, behangen mit Larvenbrut, züchtet der Stock seine Jungen, und eine Königin herrscht von innen über sie. {link:hol-anyee-marshal}Hol'anyee Marshal{/link} erforschte die Gorishi, als ihre Expedition floh. In ihren Augen gehören sie überhaupt nicht in den Krater.]=],
		},
	},
})

Translate("deDE", "terror-run", {
	title = "Terrorflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Terrorflucht ist die südwestliche Ebene des Kraters, und sie hat sich ihren Namen verdient. Stegodonten grasen in schweren Herden darauf, und Teufelssaurier jagen zwischen ihnen. Die Marshal Expeditions kamen hierher, um nach den Knochen toter Tiere zu graben. Die Gräber stellten bald fest, dass die lebenden weit zahlreicher waren, und weit gefährlicher. {link:spark-nilminer}Spark Nilminer{/link}, der oberste Gräber der Expedition, spricht noch immer mit offenem Grauen von dem Ort. Er nennt ihn eine Todesfalle, und er meint es nicht als Scherz.]=],
		},
	},
})

Translate("deDE", "fungal-rock", {
	title = "Fungal Rock",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fungal Rock ist eine Senke voller Höhlen im Nordosten des Kraters, und sie ist der Unterschlupf der großen Affen von {link:un-goro-crater}Un'Goro{/link}. Gorillas, Stampfer und Donnerer verteidigen sie, und keiner ist wilder als der mächtige Affe, den der {link:tauren}Tauren{/link}-Jäger {link:torwa-pathfinder}Torwa{/link} {link:u-cha}U'cha{/link} nennt. Die Erfinderin {link:karna-remtravel}Karna Remtravel{/link} schickte ihren mechanischen Affen {link:a-me-01}A-Me 01{/link} in diese Höhlen, um die Affen aus der Nähe zu beobachten. Die Affen ließen sich nicht lange täuschen. Als Reisende sie wiederfanden, lag sie stumm und schwer verbeult am Eingang der Höhlen.]=],
		},
	},
})

Translate("deDE", "the-marshlands", {
	title = "Die Marschen",
	aliases = { "Marschen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Marschen sind das feuchte östliche Tiefland des Kraters, ein Land aus Schlamm, Schilf und stehendem Wasser. Schleime vieler Arten sammeln sich in seinen Tümpeln, und Blutblütler kriechen durch seine Dickichte. Eines der verlassenen Lager der Expedition lag auf dieser Seite des Kraters, und seine Vorräte lagen unberührt im Schlamm, lange nachdem die Forscher geflohen waren. Ein zerstörtes Floß liegt weiter südlich neben einem kleinen Teich, fern von jedem Wasser, das es dorthin hätte tragen können. Es gehörte dem Wanderer {link:linken}Linken{/link}, auch wenn er sich nicht mehr daran erinnerte.]=],
		},
	},
})

Translate("deDE", "crystal-pylons", {
	title = "Kristallpylonen",
	aliases = { "Pylonen aus Kristall", "die Pylonen von Un'Goro" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drei Pylonen aus Kristall stehen in der Wildnis des {link:un-goro-crater}Un'Goro{/link}-Kraters: einer im Norden, einer an der Ostwand und einer im Westen. Sie sind hohe Bauwerke aus Stein, innen mit Kristall ausgekleidet, und sie sind weit älter als das Lager jedes lebenden Forschers. Lange Zeit waren sie nur Gerüchte, die man sich in {link:marshal-s-refuge}Marshals Zuflucht{/link} erzählte.]=],
		},
		{
			title = "Die Kristalle",
			text = [=[Farbige Kristalle liegen verstreut auf dem Boden des Kraters: rote, blaue, gelbe und grüne. Die meisten Reisenden beachten sie nicht. Die Gnomin {link:j-d-collie}J.D. Collie{/link} tat es. Sie sammelte sie sackweise und versuchte jede Kombination, die ihr einfiel, doch sie gaben nichts preis, bis die Pylonen gefunden wurden. Nachdem Reisende alle drei untersucht hatten, arbeitete sie durch, was sie gesehen hatten, und schrieb ihre Erkenntnisse in ein Handbuch. Damit ließen sich die Kristalle zu Verbindungen verschmelzen, die ihre Träger wiederherstellen, stärken, schützen und aufladen.]=],
		},
		{
			title = "Unbeantwortet",
			text = [=[Wer die Pylonen errichtete und zu welchem Zweck, sagt {link:un-goro-crater}der Krater{/link} nicht. {link:j-d-collie}J.D. Collie{/link} lernte, ihre Kristalle zu nutzen. Sie lernte nicht, warum sie dort waren.]=],
		},
	},
})

Translate("deDE", "williden-marshal", {
	title = "Williden Marshal",
	subtitle = "Anführer der Marshal Expeditions",
	found = "Marshals Zuflucht, zwischen den Zelten",
	hint = [=[Sprecht mit dem Anführer der Expedition, die auf den nördlichen Höhen des Kraters Zuflucht fand.]=],
	allegiance = "Marshal Expeditions",
	aliases = { "Williden" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Williden Marshal führt die Marshal Expeditions, eine Truppe von Forschern, die keiner Nation unterstehen. Er brachte sie in den {link:un-goro-crater}Un'Goro-Krater{/link}, um ihn zu erforschen, und der Krater hätte sie beinahe alle getötet. Nun hält er, was von seinen Leuten übrig ist, auf den felsigen Höhen am Leben, die seinen Namen tragen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Williden ist der Grund, warum es im Krater überhaupt sicheren Boden gibt. {link:refuge-pointe}Die Zuflucht{/link}, die seine Leute auf ihrer Flucht errichteten, ist zum Treffpunkt aller geworden, die nach {link:un-goro-crater}Un'Goro{/link} kommen, ob aus freien Stücken oder durch Unglück. Er tut nicht so, als sei die Expedition gut verlaufen. Er gibt zu, dass seine Truppe die Wildheit des Kraters viel zu leicht nahm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte die Expedition, die Lager im Südwesten und Nordosten des Kraters errichtete.
• Als die Tiere beide Lager überrannten, führte er die Überlebenden nach Norden auf höheren Grund.
• Er bittet Reisende, die Nahrung und die Forschungsausrüstung zurückzuholen, die seine Leute zurückließen.
• Er führt ein Tagebuch der Expedition, das auf der Flucht verloren ging.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Aufzeichnung sagt, woher Williden kam oder wie er seine Truppe gründete. Dieser Eintrag verzeichnet nur, was {link:un-goro-crater}der Krater{/link} aus ihm gemacht hat.]=],
		},
	},
	chapters = {
		{
			title = "Die Rettung der Expedition",
			hint = "Holt zurück, was die Expedition auf ihrer Flucht zurückließ.",
			text = [=[Die Lager waren in Eile verlassen worden, und mit ihnen die Nahrung der Expedition und ihre Instrumente. Ohne das eine würden die Forscher verhungern. Ohne das andere wäre all ihr Leiden umsonst gewesen. Als beides zur Zuflucht zurückgebracht wurde, erklärte Williden, die Expedition selbst sei gerettet, und er zählte den, der sie gerettet hatte, auf Lebenszeit zu den Freunden seiner Truppe.]=],
		},
		{
			title = "Das zerfledderte Tagebuch",
			hint = "Bringt ein verlorenes Tagebuch seinem Besitzer zurück.",
			text = [=[Draußen in der Wildnis wurde ein zerrissenes und zertrampeltes Tagebuch gefunden. Genug davon ließ sich noch lesen, um die Geschichte der Expedition zu erzählen: die überrannten Lager, die Flucht, die Suche nach höherem Grund im Norden. Williden hatte es zu den vielen Dingen gezählt, die {link:un-goro-crater}der Krater{/link} ihm genommen hatte. Er war froh, es zurückzuhaben.]=],
		},
	},
	mentions = {
		{ text = "Die Rettung der Expedition" },
		{ text = "Willidens Tagebuch" },
	},
	bonds = {
		{ id = "hol-anyee-marshal", name = "Hol'anyee Marshal", note = "teilt seinen Namen und seine Expedition" },
		{ id = "spark-nilminer", name = "Spark Nilminer", note = "sein oberster Gräber" },
	},
})

Translate("deDE", "hol-anyee-marshal", {
	title = "Hol'anyee Marshal",
	subtitle = "Gelehrte der Marshal Expeditions",
	found = "Marshals Zuflucht, neben Williden",
	hint = [=[Sprecht mit der Gelehrten der Expedition, die neben ihrem Anführer steht.]=],
	allegiance = "Marshal Expeditions",
	aliases = { "Hol'anyee" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hol'anyee Marshal ist eine Gelehrte der Marshal Expeditions. Bevor die Expedition nach Norden floh, erforschte sie die Gorishi-Insekten im Süden des Kraters. Der Rückzug beendete ihre Arbeit nicht. Sie glaubt, dass die Gorishi dem Leben des Kraters fremd sind, und sie will herausfinden, wie sie dorthin kamen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hol'anyee ist die Erste, die laut ausspricht, dass der Stock der Gorishi nicht nach {link:un-goro-crater}Un'Goro{/link} gehört.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie erforschte die Gorishi im Süden, bevor die Lager überrannt wurden.
• Sie schickte ein Schabefläschchen in den Stock, um eine Probe von den Wänden seiner Brutkammern zu nehmen.]=],
		},
	},
	mentions = {
		{ text = "Fremde Ökologie" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "führt die Expedition" },
	},
})

Translate("deDE", "spark-nilminer", {
	title = "Spark Nilminer",
	subtitle = "Oberster Gräber der Marshal Expeditions",
	found = "Marshals Zuflucht",
	hint = [=[Findet den Gräber der Expedition, der das Graben nicht mehr sonderlich liebt.]=],
	allegiance = "Marshal Expeditions",
	aliases = { "Spark" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Spark Nilminer ist der oberste Gräber der Marshal Expeditions. Seine Aufgabe war es, die Knochen toter Stegodonten und Diemetradons aus der {link:terror-run}Terrorflucht{/link} zu graben. Die lebenden Tiere machten diese Arbeit fast unmöglich, und Spark hasst den Ort inzwischen. {link:williden-marshal}Williden{/link} und {link:hol-anyee-marshal}Hol'anyee{/link} wollen ihre Knochen noch immer, und Spark möchte lieber nicht fragen, wie sie beschafft werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Spark spricht für die gewöhnlichen Mitglieder der Expedition, die zum Arbeiten kamen und nun nur noch lebend fortwollen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wurde ausgeschickt, um in der {link:terror-run}Terrorflucht{/link} nach Knochen zu graben.
• Er nimmt Knochen aus jeder Quelle und bittet Reisende, darüber zu schweigen, woher sie stammen.]=],
		},
	},
	mentions = {
		{ text = "Knochenrollen" },
	},
	bonds = {
		{ id = "williden-marshal", name = "Williden Marshal", note = "sein Anführer" },
	},
})

Translate("deDE", "j-d-collie", {
	title = "J.D. Collie",
	subtitle = "Kristallforscherin",
	found = "Die Höhle über Marshals Zuflucht",
	hint = [=[Sucht die Gnomin, die in der Höhle über der Zuflucht mit leuchtenden Kristallen arbeitet.]=],
	allegiance = "Marshals Zuflucht",
	aliases = { "J.D." },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[J.D. Collie ist eine Gnomin, die ihre Werkstatt in der Höhle über {link:marshal-s-refuge}Marshals Zuflucht{/link} eingerichtet hat. Sie ist fasziniert von den farbigen Kristallen, die überall in {link:un-goro-crater}Un'Goro{/link} liegen, und von den Gerüchten über große Pylonen draußen in der Wildnis. Sie glaubt fast jede Geschichte, die sie hört, und im Krater hat ihr dieses Vertrauen überraschend gute Dienste geleistet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[J.D. ist die Erste, die den {link:crystal-pylons}Kristallpylonen{/link} einen Sinn abgewinnt. Andere gingen jahrelang an den Kristallen vorbei. Sie sammelte sie, prüfte sie und lernte zuletzt, ihre Macht zu binden. Sie war auch freundlich zu dem Wanderer {link:linken}Linken{/link}, als er zum ersten Mal in die Zuflucht stolperte, und die wenigen Worte, die er in seiner Verwirrung zu ihr sprach, waren der Schlüssel zu seinem Gedächtnis.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sammelt Kristalle in vier Farben und prüft sie in endlosen Kombinationen.
• Sie schickt Reisende aus, um den nördlichen, den östlichen und den westlichen Pylon zu finden.
• Sie schrieb ein Handbuch der Pylonen und der Kristalle.
• Sie lenkte die Suche nach Linkens Vergangenheit zu {link:eridan-bluewind}Eridan Bluewind{/link} im {link:felwood}Teufelswald{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die drei Pylonen",
			hint = "Findet die Kristallpylonen, von denen J.D. gehört hat.",
			text = [=[Lange führten J.D.s Experimente zu nichts, und sie begann zu fürchten, dass die Kristalle überhaupt keine Macht besaßen. Dann fanden Reisende die Pylonen einen nach dem anderen: einen im Norden, einen an der Ostwand, einen im Westen. Sie nahm, was sie gesehen hatten, und arbeitete es in ihrer Höhle durch. Als sie fertig war, wusste sie, wie sich die Kristalle verbinden ließen, und sie schrieb alles in einem Buch nieder.]=],
		},
		{
			title = "Die Erinnerung einer Gnomin",
