			text = [=[Als {link:linken}Linken{/link} zum ersten Mal in die Zuflucht kam, war er benommen und voller seltsamen Gemurmels. J.D. erinnerte sich an eine Sache, die er gesagt hatte: dass er ein Totem anfertige und dass er jemanden namens {link:eridan-bluewind}Eridan Bluewind{/link} im {link:felwood}Teufelswald{/link} finden müsse. Es war ein dünner Faden, doch er führte bis zu {link:blazerunner}Blazerunner{/link}.]=],
		},
	},
	mentions = {
