		{ text = "Linkens Erinnerung" },
		{ text = "Aquementas, das Totem, das ihr gebracht wurde" },
		{ text = "Linkens Abenteuer" },
	},
	bonds = {
		{ id = "linken", name = "Linken", note = "sie erinnerte sich an das, was er vergaß" },
