})

Translate("deDE", "linken", {
	title = "Linken",
	subtitle = "Der Wanderer ohne Gedächtnis",
	found = "Marshals Zuflucht",
	hint = [=[Sprecht mit dem Wanderer in der Zuflucht, der sich nicht erinnern kann, wie er dorthin kam.]=],
	allegiance = "Keine, an die er sich erinnern kann",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Linken ist ein {link:gnomes}Gnom{/link}, der ohne Erinnerung daran, wer er war oder warum er gekommen war, im {link:un-goro-crater}Un'Goro-Krater{/link} ankam. Er weiß nur, dass ihn etwas Wichtiges hierhergeführt hat. Anders als die meisten seines Volkes hat er kein Interesse an Apparaten. {link:j-d-collie}J.D. Collie{/link} vermutet, dass er im Herzen ein Krieger ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Linkens vergessener Auftrag erweist sich als eine der großen Taten des Kraters. Er kam, um sich {link:blazerunner}Blazerunner{/link} zu stellen, dem flammenumhüllten Elementar des Feuerfedergrats, und ihm ein Artefakt schrecklicher Macht abzunehmen. Als sein Gedächtnis zurückkehrt, beansprucht er die Tat nicht für sich. Er überlässt sie dem, der ihn wiederhergestellt hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kam auf einer langen Reise nach {link:un-goro-crater}Un'Goro{/link}, deren letzter Schritt die Niederlage Blazerunners war.
• Er suchte bei {link:eridan-bluewind}Eridan Bluewind{/link} aus dem {link:felwood}Teufelswald{/link} ein Totem, stark genug, um Blazerunners Aura abzustreifen.
• Er will die Goldene Flamme in seine Heimat zurückbringen, wo sie nie wieder zum Bösen genutzt werden kann.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Linkens Heimat wird nicht genannt, und er hat nicht gesagt, wer er war, bevor er sein Gedächtnis verlor.]=],
		},
	},
	chapters = {
		{
			title = "Das verlorene Bündel",
			hint = [=[Bringt ein verlorenes Bündel seinem Besitzer in der Zuflucht zurück.]=],
			text = [=[Ein zerstörtes Floß lag neben einem kleinen Teich, fern von jedem Wasser, das es hätte tragen können. Auf dem Grund des Teichs lag ein durchnässtes Bündel: ein Kompass, eine zusammengerollte Karte und ein Schlüssel in der Form eines Löwenkopfes. Linken betrachtete sie, und etwas regte sich. Er erinnerte sich an ein Schwert, das er stärken musste, wenn auch nicht, warum. Er schickte es nach Norden zu {link:donova-snowden}Donova Snowden{/link} in {link:winterspring}Winterspring{/link}.]=],
		},
		{
			title = "Das gehärtete Schwert",
			hint = "Seht zu, wie Linkens Schwert vollendet wird.",
			text = [=[Das Schwert ging von Hand zu Hand. {link:donova-snowden}Donova{/link} härtete es in ihren heißen Quellen. Ein Elixier von {link:gregan-brewspewer}Gregan Brewspewer{/link} aus {link:feralas}Feralas{/link} ließ seinen Träger nahe {link:gadgetzan}Gadgetzan{/link} als Geist wandeln und mit dem Geist {red:gaeriyan}Gaeriyan{/red} sprechen. Unter einem Grabstein dort wurde das Schwert in einem Lichtblitz verwandelt. Linken hielt es wieder in Händen und konnte noch immer nicht sagen, wofür es war.]=],
		},
		{
			title = "Die Goldene Flamme",
			hint = "Vollendet, wozu Linken in den Krater kam.",
			text = [=[Das Totem des Aquementas brachte endlich sein Gedächtnis zurück. Da wusste Linken, dass er gekommen war, um gegen {link:blazerunner}Blazerunner{/link} zu kämpfen, der die Goldene Flamme bewachte. Er wusste auch, dass er nicht mehr derjenige war, der es tun sollte. Als Blazerunner fiel und ihm die Flamme gebracht wurde, versprach er, sie heimzutragen und sicher zu verwahren.]=],
		},
	},
	mentions = {
		{ text = "Es ist ein Geheimnis für alle" },
		{ text = "Es ist ein Geheimnis für alle, das verlorene Bündel" },
		{ text = "Es ist ein Geheimnis für alle, das Schwert" },
		{ text = "Das Videre-Elixier" },
		{ text = "Treffen am Grab" },
		{ text = "Eine ernste Lage" },
		{ text = "Linkens Schwert" },
		{ text = "Die Hilfe einer Gnomin" },
		{ text = "Silbernes Herz" },
		{ text = "Aquementas" },
		{ text = "Linkens Abenteuer" },
		{ text = "Es ist gefährlich, allein zu gehen" },
	},
	bonds = {
		{ id = "j-d-collie", name = "J.D. Collie", note = "erinnerte sich an seine Worte" },
		{ id = "blazerunner", name = "Blazerunner", note = "der Feind, dem er sich stellen wollte" },
		{ id = "donova-snowden", name = "Donova Snowden", note = "härtete sein Schwert" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "wusste, was er suchte" },
	},
})

Translate("deDE", "karna-remtravel", {
	title = "Karna Remtravel",
	subtitle = "Erfinderin von A-Me 01",
	found = "Gleich östlich von Marshals Zuflucht",
