			text = [=[Karna Remtravel ist eine Erfinderin, die die Affen von {link:un-goro-crater}Un'Goro{/link} aus der Nähe erforschen wollte. Sie baute einen mechanischen Affen, der unter ihnen leben sollte, mit Spähjuwelen als Augen, damit sie alles sehen konnte, was er sah. Sie nannte ihn {link:a-me-01}A-Me 01{/link}. Er erreichte {link:fungal-rock}Fungal Rock{/link}, und dann wurde das Bild dunkel: Das Letzte, was sie sah, war ein Alphamännchen, das auf ihn zustürmte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Karnas Arbeit ist ein kühner und kostspieliger Weg, die Geheimnisse des Kraters zu erfahren.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie baute {link:a-me-01}A-Me 01{/link} und schickte sie nach {link:fungal-rock}Fungal Rock{/link}.
• Sie bittet Reisende, ihre verlorene Maschine zu finden und heimzubringen.]=],
		},
	},
	mentions = {
		{ text = "Die Jagd nach {link:a-me-01}A-Me 01{/link}" },
		{ text = "Die Jagd nach {link:a-me-01}A-Me 01{/link}, die Rückkehr" },
	},
	bonds = {
		{ id = "a-me-01", name = "A-Me 01", note = "ihre Schöpfung" },
	},
})

