	allegiance = "Karna Remtravel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[A-Me 01 ist ein mechanischer Affe, den {link:karna-remtravel}Karna Remtravel{/link} baute, um sich unter die Gorillas von {link:un-goro-crater}Un'Goro{/link} zu mischen. Ihre Augen sind Spähjuwelen, durch die ihre Schöpferin sehen kann. Sie wurde nach {link:fungal-rock}Fungal Rock{/link} geschickt, wo einer der großen Affen sie mit seinen Fäusten begrüßte.]=],
		},
