• Nachdem ein ausgebranntes Gehäuse ersetzt war, erwachte sie und ging heim zu ihrer Schöpferin.]=],
		},
	},
	chapters = {
		{
			title = "Heim zu Karna",
			hint = "Bringt A-Me 01 zu ihrer Schöpferin zurück.",
			text = [=[Mit einem neuen Mithrilgehäuse im Rücken und einem Schalter, der aus- und wieder eingeschaltet wurde, erwachte A-Me 01 zum Leben. Die Gorillas waren nicht weit. Sie ging unter Geleitschutz durch den Dschungel zurück zu {link:karna-remtravel}Karna{/link}, verbeult, aber heil.]=],
		},
	},
	mentions = {
		{ text = "Die Jagd nach A-Me 01" },
		{ text = "Die Jagd nach A-Me 01, das Mithrilgehäuse" },
		{ text = "Die Jagd nach A-Me 01, der Heimweg" },
	},
	bonds = {
		{ id = "karna-remtravel", name = "Karna Remtravel", note = "ihre Schöpferin" },
	},
})

