Translate("deDE", "spraggle-frock", {
	title = "Spraggle Frock",
	subtitle = "Ein ängstlicher Reisender",
	found = "Marshals Zuflucht",
	hint = [=[Findet den Reisenden in der Zuflucht, der besorgt auf einen Freund wartet.]=],
	allegiance = "Marshals Zuflucht",
	aliases = { "Spraggle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Spraggle Frock ist ein Reisender, der es nicht gewagt hat, {link:marshal-s-refuge}Marshals Zuflucht{/link} zu verlassen. Die Pterrordax, die über dem Krater kreisen, versetzen ihn in Angst, und er hat einen Aushang angebracht, der jemanden sucht, ihre Zahl zu verringern, denn mit jeder Jahreszeit werden es mehr. Sein Freund {link:ringo}Ringo{/link} war kühner. Ringo zog nach Süden, um den Vulkan zu erkunden, und kehrte nicht zurück.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Spraggle ist der Beweis, dass nicht jeder im Krater auf der Suche nach Gefahr kam.]=],
		},
		{
			title = "Taten",
			text = [=[• Er brachte die Warnung vor den Pterrordax an.
• Er schickte seine Feldflasche mit jenen nach Süden, die nach {link:ringo}Ringo{/link} suchten.
• Er hofft, sich eines Tages sicher genug zu fühlen, um die Zuflucht zu verlassen.]=],
		},
	},
	mentions = {
		{ text = "Verirrt!" },
		{ text = "Ein wenig Hilfe von meinen Freunden" },
		{ text = "Hütet Euch vor Pterrordax" },
	},
	bonds = {
		{ id = "ringo", name = "Ringo", note = "sein Freund" },
	},
})

Translate("deDE", "ringo", {
