	subtitle = "Erforscher des Vulkans",
	found = "Die Hänge des Feuerfedergrats, später Marshals Zuflucht",
	hint = [=[Durchsucht die Hänge des Vulkans nach einem Forscher, der nie heimkehrte.]=],
	allegiance = "Marshals Zuflucht",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ringo ist der Freund von {link:spraggle-frock}Spraggle Frock{/link}. Er brach von der Zuflucht auf, um den Feuerfedergrat zu erkunden, und die Hitze des Vulkans überwältigte ihn. Man fand ihn benommen an dessen Hängen, und er konnte kaum gehen. Mit Wasser aus Spraggles Feldflasche, das man ihm jedes Mal ins Gesicht spritzte, wenn er ohnmächtig wurde, schaffte er es zurück zur Zuflucht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ringos knappes Entkommen ist eine Warnung an jeden Forscher, der glaubt, der Vulkan sei nur ein Berg. Selbst ohne seine Elementare kann der Grat allein mit seiner Hitze töten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erkundete den Feuerfedergrat und brach in der Hitze zusammen.
• Er kehrte lebend nach {link:marshal-s-refuge}Marshals Zuflucht{/link} zurück.]=],
		},
	},
	mentions = {
		{ text = "Verirrt!" },
		{ text = "Ein wenig Hilfe von meinen Freunden" },
	},
	bonds = {
		{ id = "spraggle-frock", name = "Spraggle Frock", note = "sein Freund" },
	},
})

Translate("deDE", "shizzle", {
	title = "Shizzle",
	subtitle = "Erbauer einer Flugmaschine",
	found = "Nahe Marshals Zuflucht",
	hint = [=[Findet den gestrandeten Tüftler, der sich einen Weg baut, heimzufliegen.]=],
	allegiance = "Gadgetzan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shizzle ist ein Tüftler aus {link:gadgetzan}Gadgetzan{/link}, der in {link:un-goro-crater}Un'Goro{/link} gestrandet ist. Er hat keinen Orientierungssinn, und Greifen und Windreiter machen ihm zu viel Angst, um auf ihnen zu reiten. Seine Antwort ist, seine eigene Flugmaschine zu bauen. Nur die Flügel fehlen noch, und er glaubt, dass die Schwimmhautschuppen von Pterrordax und Diemetradons taugen werden. Er hat keine Lust, diese Tiere selbst zu jagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Shizzles Antwort auf die Angst ist die Erfindung: Wenn der Weg nach Hause zu beängstigend ist, baut er eben einen neuen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er baut einen Flieger, der ihn zurück nach {link:gadgetzan}Gadgetzan{/link} tragen soll.]=],
		},
	},
	mentions = {
		{ text = "Shizzles Flieger" },
	},
})

Translate("deDE", "krakle", {
